window.consolidateFamilyMovementsV173=function(rows=[]){
  const sorted=[...(rows||[])].sort((a,b)=>String(a.criadoEm||'').localeCompare(String(b.criadoEm||''))),used=new Set(),out=[];
  const payTypes=new Set(['pagamento_venda_online_secretaria','pagamento_venda_secretaria']);
  const saleTypes=new Set(['venda_secretaria_online','venda_secretaria']);
  const keyOf=x=>String(x.vendaId||x.orderNsu||'');
  const moveKind=x=>String(x.subtipo||x.tipo||'');
  for(let i=0;i<sorted.length;i++){
    const a=sorted[i];if(used.has(a.id))continue;const sub=moveKind(a);
    if(payTypes.has(sub)||saleTypes.has(sub)){
      const key=keyOf(a);let j=-1;
      if(key){
        const opposite=payTypes.has(sub)?saleTypes:payTypes;
        j=sorted.findIndex((b,idx)=>idx!==i&&!used.has(b.id)&&opposite.has(moveKind(b))&&keyOf(b)===key);
      }
      if(j>=0){const b=sorted[j],purchase=saleTypes.has(moveKind(a))?a:b,payment=payTypes.has(moveKind(a))?a:b,total=Math.abs(n(purchase.valorCompraCentavos||purchase.valorCentavos)),external=Math.abs(n(payment.valorCentavos)),impact=signedImpact(payment)+signedImpact(purchase),created=String(purchase.criadoEm||payment.criadoEm||'');used.add(a.id);used.add(b.id);out.push({...purchase,id:`op_${purchase.id}_${payment.id}`,_composite:true,_movementIds:[purchase.id,payment.id],_purchase:purchase,_payment:payment,valorCompraCentavos:total,valorPagoExternoCentavos:external,impactoSaldoCentavos:impact,valorCentavos:impact,saldoDepoisCentavos:purchase.saldoDepoisCentavos,criadoEm:created,subtipo:'compra_secretaria_consolidada',tipo:'operacao_compra',formaPagamento:purchase.formaPagamento||payment.formaPagamento,orderNsu:purchase.orderNsu||payment.orderNsu,vendaId:purchase.vendaId||payment.vendaId,itens:purchase.itens||[]});continue}
    }
    used.add(a.id);out.push(a);
  }
  return out.sort((a,b)=>String(b.criadoEm||'').localeCompare(String(a.criadoEm||'')));
};
function compositeTitle(m){return String(m._purchase?.subtipo||m._purchase?.tipo||'').includes('online')?'Compra online — Secretaria':'Compra — Secretaria'}
function compositeDesc(m){const total=n(m.valorCompraCentavos),external=n(m.valorPagoExternoCentavos),used=Math.max(0,total-external),regularized=Math.max(0,external-total),parts=[`Compra ${fmt(total)}`];if(external)parts.push(`pagamento externo ${fmt(external)}`);if(used)parts.push(`saldo da família ${fmt(used)}`);if(regularized)parts.push(`regularização anterior ${fmt(regularized)}`);return parts.join(' · ')}
async function familyQuery(collection,students){if(typeof window.queryFamilyRecordsV221==='function')return window.queryFamilyRecordsV221(collection,students,{arrayField:'alunosIds',mode:'compact'});const seen=new Map(),jobs=[];for(const a of students){jobs.push(db.collection(collection).where('alunoId','==',a.id).limit(150).get().catch(()=>({docs:[]})));jobs.push(db.collection(collection).where('alunosIds','array-contains',a.id).limit(150).get().catch(()=>({docs:[]})))}for(const s of await Promise.all(jobs))for(const d of s.docs)seen.set(d.id,{id:d.id,...d.data()});return [...seen.values()]}
