function renderParentMovementsV173(){const students=currentFamilyStudents(),filter=state.v173ParentMoveFilter||'todos',rows=(state.v173ParentMoves||[]).filter(x=>moveBelongs(x,filter)),bar=students.length>1?`<div class="v172-filter-bar"><button class="btn ${filter==='todos'?'btn-primary':'btn-light'}" onclick="setParentMovementFilterV173('todos')">Todos</button>${students.map(a=>`<button class="btn ${String(filter)===String(a.id)?'btn-primary':'btn-light'}" onclick="setParentMovementFilterV173('${safeJs(a.id)}')">${esc((a.nome||'Aluno').split(' ')[0])}</button>`).join('')}</div>`:'';document.getElementById('modalBody').innerHTML=`${bar}${rows.length?`<div class="v151-list">${rows.map(m=>{const composite=Boolean(m._composite),impact=composite?n(m.impactoSaldoCentavos):signedImpact(m),title=composite?compositeTitle(m):movementLabelV151(m),desc=composite?compositeDesc(m):movementDescriptionV151(m),detailId=composite?(m._purchase?.id||m._movementIds?.[0]):m.id,orderNsu=m.orderNsu||'';return `<div class="v151-ledger-card v173-ledger-card"><div><strong>${humanDate(m.criadoEm)}</strong><div class="muted" style="font-size:11px">${esc(methodLabelV151(m.formaPagamento||m.origem))}</div></div><div>${movementStudentRefsV173(m)}<strong>${esc(title)}</strong><div class="muted" style="font-size:12px;margin-top:3px">${desc}</div>${m.saldoDepoisCentavos!==undefined?`<div class="muted" style="font-size:11px;margin-top:4px">Saldo após: ${signedV151(m.saldoDepoisCentavos)}</div>`:''}<div class="actions" style="margin-top:7px"><button class="btn btn-light" onclick="openMovementDetailV162('${safeJs(detailId)}','parent')">Detalhar</button>${orderNsu?`<button class="btn btn-outline" onclick="openParentReceiptMenuV156('${safeJs(detailId)}','${safeJs(orderNsu)}')">Comprovante</button>`:''}</div></div><div class="v173-transaction-value"><small>${composite?'Valor da compra':'Impacto no saldo'}</small><strong>${composite?fmt(m.valorCompraCentavos):(impact>=0?'+':'')+fmt(impact)}</strong>${composite&&impact!==0?`<span>Saldo ${(impact>=0?'+':'')+fmt(impact)}</span>`:''}</div></div>`}).join('')}</div>`:'<div class="empty">Nenhuma movimentação neste filtro.</div>'}`}
