/* ===============================
   PEDIDOS: KPIs GERAIS + KPIs POR CATEGORIA
   =============================== */
function isoWeekEnd(){const d=new Date(`${dateKey()}T12:00:00`);d.setDate(d.getDate()+7);return d.toISOString().slice(0,10)}
function dueFlags(row,occ){const today=dateKey(),end=isoWeekEnd();if(row._kind==='cantina'){const o=occ.filter(x=>x.pedidoId===row.id&&!FINAL_ORDER.has(String(x.status||''))),dates=o.map(x=>String(x.dataChave||''));return{today:dates.includes(today),week:dates.some(x=>x>=today&&x<=end),scheduled:dates.some(x=>x>=today)}}const due=String(row.dataEntrega||row.dataEvento||row.dataAgendada||row.dataChave||'').slice(0,10);return{today:due===today,week:Boolean(due&&due>=today&&due<=end),scheduled:Boolean(due&&due>=today)}}
function recentFlag(row){const t=new Date(row.criadoEm||0).getTime();return Number.isFinite(t)&&t>=Date.now()-7*86400000}
function orderSpecificCards(cat,rows,occ){const list=cat==='todos'?rows:rows.filter(r=>r._category===cat),open=list.filter(r=>!FINAL_ORDER.has(String(r.statusAtendimento||r.statusPedido||''))),recent=list.filter(recentFlag);if(cat==='cantina'){const today=occ.filter(x=>String(x.dataChave||'')===dateKey()&&!FINAL_ORDER.has(String(x.status||''))).length,scheduled=occ.filter(x=>String(x.dataChave||'')>=dateKey()&&!FINAL_ORDER.has(String(x.status||''))).length,notDone=occ.filter(x=>['aluno_ausente','nao_entregue'].includes(String(x.status||''))).length;return[['cat_today','Entregas hoje',today],['cat_scheduled','Entregas agendadas',scheduled],['cat_open','Pedidos em aberto',open.length],['cat_exceptions','Ausências / não entregues',notDone]]}if(cat==='fardamento'){return[['cat_production','Em produção',list.filter(x=>['aguardando_producao','enviado_fabrica','em_producao'].includes(String(x.statusAtendimento||''))).length],['cat_ready','Prontas para entrega',list.filter(x=>String(x.statusAtendimento||'')==='pronto_retirada').length],['cat_open','Pedidos em aberto',open.length],['cat_recent','Pedidos recentes',recent.length]]}return[['cat_open','Em aberto',open.length],['cat_week','Com data nesta semana',list.filter(r=>dueFlags(r,occ).week).length],['cat_recent','Pedidos recentes',recent.length],['cat_done','Concluídos',list.length-open.length]]}
function injectOrdersKpisV173(){const rows=state.v166OrderRows||[],occ=state.v166OrderOccurrences||[],top=document.querySelector('.v166-kpis'),tabs=document.querySelector('.v166-order-tabs');if(!top||!tabs)return;const dueToday=rows.filter(r=>dueFlags(r,occ).today).length,dueWeek=rows.filter(r=>dueFlags(r,occ).week).length,open=rows.filter(r=>!FINAL_ORDER.has(String(r.statusAtendimento||r.statusPedido||''))).length,recent=rows.filter(recentFlag).length;top.innerHTML=`${[['hoje','Entregas / compromissos hoje · janela',dueToday,'red'],['semana','Pendências da semana · janela',dueWeek,'orange'],['abertos','Pedidos em aberto · janela',open,''],['recentes','Pedidos recentes · janela',recent,'green']].map(([id,l,v,c])=>`<button class="kpi clickable ${c}" onclick="setOrdersQuickFilterV173('${id}')"><div class="kpi-label">${l}</div><div class="kpi-value">${v}</div><span class="kpi-arrow">›</span></button>`).join('')}`;let specific=document.getElementById('v173CategoryKpis');if(!specific){specific=document.createElement('div');specific.id='v173CategoryKpis';specific.className='grid g4 v173-category-kpis';tabs.insertAdjacentElement('afterend',specific)}const cat=state.v166OrdersCategory||'todos';specific.innerHTML=orderSpecificCards(cat,rows,occ).map(([id,l,v])=>`<button class="kpi clickable ${state.v173OrdersQuick===id?'v162-active-filter':''}" onclick="setOrdersQuickFilterV173('${id}')"><div class="kpi-label">${esc(l)}</div><div class="kpi-value">${v}</div><span class="kpi-arrow">›</span></button>`).join('');document.querySelectorAll('.v166-order-row').forEach((el,i)=>{const r=rows[i];if(!r)return;const f=dueFlags(r,occ);el.dataset.v173Today=f.today?'1':'0';el.dataset.v173Week=f.week?'1':'0';el.dataset.v173Scheduled=f.scheduled?'1':'0';el.dataset.v173Recent=recentFlag(r)?'1':'0';el.dataset.v173OrderId=r.id||'';el.dataset.v173Kind=r._kind||''});decorateStudentRows()}
window.setOrdersQuickFilterV173=function(key){state.v173OrdersQuick=state.v173OrdersQuick===key?'':key;window.filterOrdersV166()};
window.filterOrdersV166=function(){BASE_FILTER_ORDERS();const key=state.v173OrdersQuick||'',cat=state.v166OrdersCategory||'todos',occ=state.v166OrderOccurrences||[];let visible=0;document.querySelectorAll('.v166-order-row').forEach(row=>{if(row.style.display==='none')return;let ok=true;if(key==='hoje')ok=row.dataset.v173Today==='1';else if(key==='semana'||key==='cat_week')ok=row.dataset.v173Week==='1';else if(key==='recentes'||key==='cat_recent')ok=row.dataset.v173Recent==='1';else if(key==='abertos'||key==='cat_open')ok=row.dataset.statusGroup!=='concluidos';else if(key==='cat_production')ok=row.dataset.statusGroup==='producao';else if(key==='cat_ready')ok=row.dataset.statusGroup==='pronto_retirada';else if(key==='cat_done')ok=row.dataset.statusGroup==='concluidos';else if(key==='cat_today')ok=row.dataset.v173Today==='1';else if(key==='cat_scheduled')ok=row.dataset.v173Scheduled==='1';else if(key==='cat_exceptions'){const r=(state.v166OrderRows||[]).find(x=>String(x.id)===String(row.dataset.v173OrderId));ok=r?occ.some(o=>o.pedidoId===r.id&&['aluno_ausente','nao_entregue'].includes(String(o.status||''))):false}if(!ok)row.style.display='none';else visible++});const empty=document.getElementById('v166OrdersEmpty');if(!visible){if(!empty){const e=document.createElement('div');e.id='v166OrdersEmpty';e.className='empty-soft';e.textContent='Nenhum pedido encontrado para este filtro.';document.getElementById('v166OrdersList')?.appendChild(e)}}else empty?.remove();};
window.setOrdersCategoryV166=function(cat){state.v166OrdersCategory=cat||'todos';state.v173OrdersQuick='';return window.renderPedidosV166()};
window.setOrdersStatusV166=function(status){state.v166OrdersStatus=status||'';state.v173OrdersQuick='';const s=document.getElementById('v166OrdersStatus');if(s)s.value=state.v166OrdersStatus;window.filterOrdersV166()};
window.renderPedidosV166=async function(opts={}){await BASE_RENDER_ORDERS(opts);injectOrdersKpisV173();window.filterOrdersV166()};window.renderPedidos=window.renderPedidosV166;try{renderPedidos=window.renderPedidosV166}catch(_){ }try{filterOrdersV166=window.filterOrdersV166;setOrdersCategoryV166=window.setOrdersCategoryV166;setOrdersStatusV166=window.setOrdersStatusV166}catch(_){ }

